var app = new Vue({
    el: '#app',
    delimiters: ['[[', ']]'],
    data: {
        
    },
    methods: {
        uploadCsv() {
            const path = window.location.href;
            axios.post(path)
                .then((response) => {
                    this.$notify({
                        group: 'notification',
                        type: response.data["status"],
                        title: response.data["title"],
                        text: response.data["message"],
                        duration: 2500,
                        speed: 1000
                    })
                })
                .catch((error) => {
                    console.log(error);
                });
        },
        downloadCsv() {
            const path = window.location.origin + '/dashboard/download/customer';
            axios({
                url: path,
                method: 'GET',
                responseType: 'blob',
                })
                .then((response) => {
                    const url = window.URL.createObjectURL(new Blob([response.data]));
                    const link = document.createElement('a');
                    link.href = url;
                    const fileName = 'customer.csv'
                    link.setAttribute('download', fileName);
                    document.body.appendChild(link);
                    link.click();
                    link.remove();
                })
                .catch((error) => {
                    console.log(error);
                });
        },
    }
})